const req  = $input.first().json;
const body = req.body || req;

const err = (message) => [{ json: { valid: false, statusCode: 400, body: { message } } }];

// El autor sale SIEMPRE del JWT, nunca del cuerpo: si no, cualquiera podría
// atribuir una customización a otro usuario.
const userId = req.jwtPayload?.userId || null;

const id          = (body.id          || '').toString().trim();
const event_code  = (body.event_code  || '').toString().trim();
const name        = (body.name        || '').toString().trim();
const handler_ref = (body.handler_ref || '').toString().trim();
const handler_type = (body.handler_type || 'n8n_workflow').toString().trim();

if (!event_code) return err('Hay que indicar a qué evento se engancha la implementación.');
if (!name || name.length > 120) return err('El nombre es obligatorio y no puede superar los 120 caracteres.');

// v1 sólo despacha sub-workflows de n8n. La columna admite más tipos para poder
// crecer sin migración, pero el dispatcher filtra por handler_type y no sabría
// qué hacer con otra cosa.
if (handler_type !== 'n8n_workflow') {
  return err('Sólo se admiten sub-workflows de n8n en esta versión.');
}
if (!/^[A-Za-z0-9_-]{8,40}$/.test(handler_ref)) {
  return err('El ID del sub-workflow no tiene el formato esperado. Es el identificador que aparece en la URL de n8n: /workflow/<id>');
}

const seq = Number(body.seq ?? 100);
if (!Number.isInteger(seq) || seq < 0 || seq > 9999) return err('El orden debe ser un entero entre 0 y 9999.');

const mode = (body.mode || 'sync').toString().trim();
if (mode !== 'sync' && mode !== 'async') return err('El modo debe ser "sync" o "async".');

const on_error = (body.on_error || 'ignore').toString().trim();
if (on_error !== 'ignore' && on_error !== 'fail') return err('La política de error debe ser "ignore" o "fail".');

const timeout_ms = Number(body.timeout_ms ?? 30000);
if (!Number.isInteger(timeout_ms) || timeout_ms < 1000 || timeout_ms > 300000) {
  return err('El tiempo límite debe estar entre 1000 y 300000 ms.');
}

let config = body.config ?? {};
if (typeof config === 'string') {
  const s = config.trim();
  if (!s) config = {};
  else {
    try { config = JSON.parse(s); }
    catch (e) { return err('La configuración no es JSON válido.'); }
  }
}
if (typeof config !== 'object' || Array.isArray(config) || config === null) {
  return err('La configuración debe ser un objeto JSON.');
}

return [{ json: {
  valid: true,
  id: id || null,
  event_code, name, handler_type, handler_ref, seq, mode, on_error, timeout_ms,
  description: (body.description || '').toString().trim() || null,
  config:      JSON.stringify(config),
  log_enabled: body.log_enabled !== false,
  is_active:   body.is_active   !== false,
  created_by:  userId,
} }];

const r = $input.first()?.json || {};

if (r.error) {
  const msg = (r.error?.message || String(r.error));
  if (msg.includes('uq_hook_registry_event_handler') || msg.includes('duplicate key')) {
    return [{ json: { statusCode: 409, body: { message: 'Ese sub-workflow ya está registrado en este evento.' } } }];
  }
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la implementación: ' + msg } } }];
}

if (r.violacion === 'unknown_event') {
  return [{ json: { statusCode: 400, body: { message: 'El evento indicado no existe en el catálogo.' } } }];
}
if (r.violacion === 'before_async') {
  return [{ json: { statusCode: 400, body: { message: 'Un hook de un evento "antes de" debe ejecutarse en modo síncrono: en modo asíncrono no puede devolver cambios ni frenar la operación.' } } }];
}

if (!r.registro) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la implementación.' } } }];
}

return [{ json: { statusCode: 200, body: r.registro } }];
